<?php
namespace Tests\Feature;
use App\Models\{User,ConnectedAdAccount,PerformanceMetric};
use App\Services\Advertising\{OAuthManager,Contracts\AdvertisingProviderInterface};
use App\Services\Advertising\Adapters\{GoogleAdsAdapter,TikTokAdsAdapter,SnapchatAdsAdapter,TaboolaAdsAdapter};
use App\Services\Advertising\Sync\AdDataSyncEngine;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\Http;
use Mockery;
use Tests\TestCase;
final class SharedNormalizationBoundaryTest extends TestCase {
 use DatabaseTransactions;
 private function account(string $provider):ConnectedAdAccount{return ConnectedAdAccount::create(['user_id'=>User::factory()->create()->id,'provider'=>$provider,'external_account_id'=>uniqid(),'account_name'=>'Synthetic','currency'=>'USD','timezone'=>'UTC','access_token'=>'fixture']);}
 public function test_shared_batch_rejects_fractional_counts_optional_invalid_and_unknown_before_any_write():void{
  $a=$this->account('meta');$good=['date'=>'2026-11-01','spend'=>10,'impressions'=>100,'clicks'=>2,'conversions'=>1.5,'conversion_value'=>20];foreach([['impressions'=>1.5],['clicks'=>true],['frequency'=>'bad'],['reach'=>2.1],['spend'=>null],['conversion_value'=>INF]]as$bad){$adapter=Mockery::mock(AdvertisingProviderInterface::class);$adapter->shouldReceive('fetchCampaigns')->andReturn(['campaigns'=>[]]);$adapter->shouldReceive('fetchInsights')->andReturn(['metrics'=>[$good,array_replace($good,['date'=>'2026-11-02'],$bad)]]);$manager=Mockery::mock(OAuthManager::class);$manager->shouldReceive('getAdapter')->andReturn($adapter);$run=(new AdDataSyncEngine($manager))->syncAccount($a,'manual','2026-11-01','2026-11-02');$this->assertSame('failed',$run->status);$this->assertSame(0,PerformanceMetric::where('connected_ad_account_id',$a->id)->count());}
 }
 public function test_original_provider_raw_fields_reject_malformed_values_not_coerced_zeros():void{
  foreach(['google','tiktok','snapchat','taboola']as$provider){$a=$this->account($provider);Http::swap(new \Illuminate\Http\Client\Factory);Http::preventStrayRequests();$json=match($provider){'google'=>['results'=>[['campaign'=>['id'=>'c'],'segments'=>['date'=>'2026-11-01'],'metrics'=>['costMicros'=>'bad','impressions'=>100,'clicks'=>2,'conversions'=>1,'conversionsValue'=>20]]]],'tiktok'=>['code'=>0,'data'=>['list'=>[['dimensions'=>['campaign_id'=>'c','stat_time_day'=>'2026-11-01'],'metrics'=>['spend'=>'bad','impressions'=>100,'clicks'=>2,'conversion'=>1,'total_purchase_value'=>20]]],'page_info'=>['total_page'=>1]]],'snapchat'=>['request_status'=>'SUCCESS','timeseries_stats'=>[['sub_request_status'=>'SUCCESS','timeseries_stat'=>['timeseries'=>[['start_time'=>'2026-11-01T00:00:00Z','stats'=>['spend'=>'bad','impressions'=>100,'swipes'=>2,'conversion_purchases'=>1,'conversion_purchases_value'=>20]]]]]]],default=>['results'=>[['date'=>'2026-11-01','spent'=>'bad','impressions'=>100,'clicks'=>2,'cpa_actions_num'=>1,'conversions_value'=>20]]]};Http::fake(['*'=>Http::response($json)]);$adapter=match($provider){'google'=>new GoogleAdsAdapter(new \App\Models\ProviderDeveloperConfig(['provider'=>'google','app_id'=>'fixture','app_secret'=>'fixture','developer_token'=>'fixture'])),'tiktok'=>new TikTokAdsAdapter,'snapchat'=>new SnapchatAdsAdapter,default=>new TaboolaAdsAdapter};try{$adapter->fetchInsights($a,'2026-11-01','2026-11-01');$this->fail('Coerced malformed source: '.$provider);}catch(\RuntimeException $e){$this->assertStringContainsString('metric operand',$e->getMessage());}}
 }
 public function test_additional_reporting_adapters_reject_fractional_delivery_counts():void{
  \Illuminate\Support\Carbon::setTestNow('2026-11-23T12:00:00Z');try{foreach(['pinterest','reddit','spotify','linkedin']as$p){$a=$this->account($p);Http::swap(new \Illuminate\Http\Client\Factory);Http::preventStrayRequests();
   $json=match($p){
    'pinterest'=>[['DATE'=>'2026-11-01','AD_ACCOUNT_ID'=>$a->external_account_id,'SPEND_IN_MICRO_DOLLAR'=>1000000,'PAID_IMPRESSION'=>1.5,'OUTBOUND_CLICK_1'=>1,'TOTAL_CHECKOUT'=>1,'TOTAL_CHECKOUT_VALUE_IN_MICRO_DOLLAR'=>2000000]],
    'reddit'=>['data'=>['metrics'=>[['date'=>'2026-11-01','currency'=>'USD','spend'=>1000000,'impressions'=>1.5,'clicks'=>1,'conversion_purchase_clicks'=>1,'conversion_purchase_views'=>0,'conversion_purchase_total_value'=>200]]]],
    'spotify'=>['rows'=>[['entity_type'=>'AD_ACCOUNT','entity_id'=>$a->external_account_id,'start_time'=>'2026-11-01T00:00:00Z','stats'=>array_map(fn($k,$v)=>['field_type'=>$k,'field_value'=>$v],['SPEND','IMPRESSIONS','CLICKS','PURCHASES','REVENUE'],[1,1.5,1,1,2])]]],
    'linkedin'=>['elements'=>[['pivotValues'=>['urn:li:sponsoredAccount:'.$a->external_account_id],'dateRange'=>['start'=>['year'=>2026,'month'=>11,'day'=>1],'end'=>['year'=>2026,'month'=>11,'day'=>1]],'costInLocalCurrency'=>1,'impressions'=>1.5,'clicks'=>1,'externalWebsiteConversions'=>1,'conversionValueInLocalCurrency'=>2]]],
    default=>[]};
   Http::fake(['*'=>Http::response($json)]);$adapter=match($p){'pinterest'=>new \App\Services\Advertising\Adapters\PinterestAdsAdapter,'reddit'=>new \App\Services\Advertising\Adapters\RedditAdsAdapter,'spotify'=>new \App\Services\Advertising\Adapters\SpotifyAdsAdapter,default=>new \App\Services\Advertising\Adapters\LinkedInAdsAdapter(new \App\Models\ProviderDeveloperConfig(['api_version'=>'202611','extra_settings'=>['conversion_values_verified_as_revenue'=>true]]))};
   try{$adapter->fetchInsights($a,'2026-11-01','2026-11-01');$this->fail('Fractional count accepted: '.$p);}catch(\RuntimeException $e){$this->assertStringContainsString('Count must be integral',$e->getMessage(),$p);}
  }}finally{\Illuminate\Support\Carbon::setTestNow();}
 }

 public function test_sync_stamps_only_current_operand_validation_and_exact_account_evidence():void{
  $a=$this->account('google');$good=['date'=>'2026-11-01','spend'=>0,'impressions'=>0,'clicks'=>0,'conversions'=>1.5,'conversion_value'=>0];
  foreach([false,true]as$explicit){$a->metadata=$explicit?['metadata_source'=>['version'=>'provider-discovery-explicit-1','currency'=>'USD','timezone'=>'UTC']]:[];$a->save();$adapter=Mockery::mock(AdvertisingProviderInterface::class);$adapter->shouldReceive('fetchCampaigns')->andReturn(['campaigns'=>[]]);$adapter->shouldReceive('fetchInsights')->andReturn(['metrics'=>[$good]]);$manager=Mockery::mock(OAuthManager::class);$manager->shouldReceive('getAdapter')->andReturn($adapter);$run=(new AdDataSyncEngine($manager))->syncAccount($a,'manual','2026-11-01','2026-11-01');$this->assertSame('completed',$run->status);$m=PerformanceMetric::where('connected_ad_account_id',$a->id)->sole();$this->assertSame('strict-operands-1',$m->metadata['normalization_version']);$this->assertSame($explicit?'provider-discovery-explicit-1':'unverified_legacy_or_missing',$m->metadata['account_metadata_source']);$this->assertSame(1.5,(float)$m->conversions);$this->assertSame(0.0,(float)$m->spend);$this->assertSame(!$explicit,(new \App\Services\Analytics\MetaDefinitionTransitionGuard)->problem([$m])!==null);}
  $a->timezone='Africa/Cairo';$this->assertSame('unverified_legacy_or_missing',\App\Services\Advertising\AccountMetadataEvidence::marker($a));
 }
 public function test_google_and_tiktok_discovery_missing_or_malformed_metadata_stays_unknown():void{
  $config=new \App\Models\ProviderDeveloperConfig(['provider'=>'google','app_id'=>'fixture','app_secret'=>'fixture','developer_token'=>'fixture']);
  foreach([null,['currencyCode'=>'bad','timeZone'=>'imaginary'],['currencyCode'=>'EGP','timeZone'=>'Africa/Cairo']]as$detail){Http::swap(new \Illuminate\Http\Client\Factory);Http::preventStrayRequests();Http::fake(['*listAccessibleCustomers'=>Http::response(['resourceNames'=>['customers/123']]),'*googleAds:search'=>Http::response(['results'=>$detail===null?[]:[['customer'=>$detail]]])]);$row=(new GoogleAdsAdapter($config))->discoverAccounts('fixture')[0];$valid=($detail['currencyCode']??null)==='EGP';$this->assertSame($valid?'EGP':null,$row['currency']);$this->assertSame($valid?'Africa/Cairo':null,$row['timezone']);$this->assertSame('provider-discovery-explicit-1',$row['metadata_source']['version']);}
  $config=new \App\Models\ProviderDeveloperConfig(['provider'=>'tiktok','app_id'=>'fixture','app_secret'=>'fixture']);Http::swap(new \Illuminate\Http\Client\Factory);Http::fake(['*'=>Http::response(['code'=>0,'data'=>['list'=>[['advertiser_id'=>'123'],['advertiser_id'=>'124','currency'=>'bad','timezone'=>'imaginary'],['advertiser_id'=>'125','currency'=>'EGP','timezone'=>'Africa/Cairo']]]])]);$rows=(new TikTokAdsAdapter($config))->discoverAccounts('fixture');foreach([0,1]as$i){$this->assertNull($rows[$i]['currency']);$this->assertNull($rows[$i]['timezone']);}$this->assertSame('EGP',$rows[2]['currency']);$this->assertSame('Africa/Cairo',$rows[2]['timezone']);
 }
 public function test_original_provider_legacy_overview_and_archives_withhold_without_editing_history():void{
  foreach(['google','tiktok','snapchat','meta']as$p){$a=$this->account($p);$row=PerformanceMetric::create(['connected_ad_account_id'=>$a->id,'provider'=>$p,'date'=>'2026-11-01','currency'=>'USD','spend'=>12,'impressions'=>100,'clicks'=>2,'conversions'=>1,'conversion_value'=>20]);$row->refresh();$before=$row->getAttributes();$this->assertNotNull((new \App\Services\Analytics\MetaDefinitionTransitionGuard)->userProblem($a->user_id,'2026-11-01','2026-11-01',$p));$archive=new \App\Models\OptimizationRun(['inputs'=>['objective'=>'MAXIMIZE_REVENUE'],'source_snapshot'=>['source_rows'=>[$before]]]);$this->assertNotNull((new \App\Services\Analytics\MetaDefinitionTransitionGuard)->archiveProblem($archive));$this->assertSame($before,$row->fresh()->getAttributes());}
 }
}
